def shape(label, counts):
    print(label)
    for i in range(len(counts)):
        print(f"  bin {i + 1} | " + "#" * counts[i])
    peaks = []
    for i in range(len(counts)):
        left = 0
        right = 0
        if i > 0:
            left = counts[i - 1]
        if i < len(counts) - 1:
            right = counts[i + 1]
        if counts[i] > left and counts[i] > right:
            peaks.append(i + 1)
    print(f"  peaks at bins: {peaks}")
    if len(peaks) == 0:
        print("  no peak: flat, uniform")
    elif len(peaks) > 1:
        print("  more than one peak: bimodal")
    else:
        p = peaks[0] - 1
        before = sum(counts[j] for j in range(p))
        after = sum(counts[j] for j in range(p + 1, len(counts)))
        print(f"  {before} values left of the peak, {after} right")
        if after > before:
            print("  the tail is on the right: skewed right")
        elif before > after:
            print("  the tail is on the left: skewed left")
        else:
            print("  balanced: symmetric")
shape("Case 1 · test scores", [2, 4, 8, 4, 2])
shape("Case 2 · clinic waits", [9, 6, 3, 1, 1])
shape("Case 3 · an easy exam", [1, 1, 3, 6, 9])
shape("Case 4 · café customers", [3, 8, 4, 2, 7, 3])
shape("Case 5 · flat", [4, 4, 4, 4])

